<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class WorkProgramController extends Controller{
 private function plan($id){$p=DB::table('curriculum_plans as cp')->join('study_groups as g','g.id','=','cp.study_group_id')->join('subjects as s','s.id','=','cp.subject_id')->leftJoin('teachers as t','t.id','=','cp.teacher_id')->where('cp.id',$id)->select('cp.*','g.name group_name','s.name subject_name','t.last_name','t.first_name')->first();abort_if(!$p,404);return $p;}
 private function access(Request $r,$p,$approve=false){$u=$r->user();$admin=$u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('academic_head');abort_unless($admin||(!$approve&&$u->teacher_id==$p->teacher_id),403);}
 public function edit(Request $r,$id){$p=$this->plan($id);$this->access($r,$p);$topics=DB::table('curriculum_topics')->where('curriculum_plan_id',$id)->orderBy('sort_order')->get();return view('curriculum.program',compact('p','topics'));}
 public function update(Request $r,$id){$p=$this->plan($id);$this->access($r,$p);PeriodGuard::writable($p->academic_period_id);abort_if($p->approval_status==='approved'&&!($r->user()->isSuperAdmin()||$r->user()->hasRole('academic_head')),423,'Утверждённая программа защищена. Создайте новую версию.');$d=$r->validate(['title'=>'nullable|string|max:255','purpose'=>'nullable|string|max:10000','learning_outcomes'=>'nullable|string|max:10000','requirements'=>'nullable|string|max:10000','assessment'=>'nullable|string|max:10000','literature'=>'nullable|string|max:10000','resources'=>'nullable|string|max:10000']);DB::table('curriculum_plans')->where('id',$id)->update($d+['updated_at'=>now()]);return back()->with('success','Рабочая программа сохранена.');}
 public function approve(Request $r,$id){$p=$this->plan($id);$this->access($r,$p,true);PeriodGuard::writable($p->academic_period_id);DB::table('curriculum_plans')->where('id',$id)->update(['approval_status'=>'approved','approved_by'=>$r->user()->id,'approved_at'=>now(),'updated_at'=>now()]);return back()->with('success','Рабочая программа утверждена.');}
 public function copy(Request $r,$id){$p=$this->plan($id);$this->access($r,$p);$d=$r->validate(['study_group_id'=>'required|exists:study_groups,id','teacher_id'=>'nullable|exists:teachers,id']);$new=DB::transaction(function()use($p,$d,$r){$nid=DB::table('curriculum_plans')->insertGetId(['academic_period_id'=>$p->academic_period_id,'study_group_id'=>$d['study_group_id'],'subject_id'=>$p->subject_id,'teacher_id'=>$d['teacher_id']??$p->teacher_id,'title'=>$p->title,'status'=>'active','version'=>$p->version+1,'purpose'=>$p->purpose,'learning_outcomes'=>$p->learning_outcomes,'requirements'=>$p->requirements,'assessment'=>$p->assessment,'literature'=>$p->literature,'resources'=>$p->resources,'approval_status'=>'draft','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);foreach(DB::table('curriculum_topics')->where('curriculum_plan_id',$p->id)->orderBy('sort_order')->get() as $x)DB::table('curriculum_topics')->insert(['curriculum_plan_id'=>$nid,'sort_order'=>$x->sort_order,'section'=>$x->section,'title'=>$x->title,'planned_hours'=>$x->planned_hours,'planned_on'=>$x->planned_on,'control_type'=>$x->control_type,'is_checkpoint'=>$x->is_checkpoint,'note'=>$x->note,'created_at'=>now(),'updated_at'=>now()]);return $nid;});return redirect()->route('curriculum.program',$new)->with('success','Создана новая версия программы.');}
 public function print(Request $r,$id){$p=$this->plan($id);$this->access($r,$p);$topics=DB::table('curriculum_topics')->where('curriculum_plan_id',$id)->orderBy('sort_order')->get();return view('curriculum.program-print',compact('p','topics'));}
}